      qty_asc: (a, b) => (a.quantity ?? 999) - (b.quantity ?? 999),
      unit_desc: (a, b) => (b.unitValue ?? -1) - (a.unitValue ?? -1),
      unit_asc: (a, b) => (a.unitValue ?? 999) - (b.unitValue ?? 999),
